function showColorPhotos(range) {
  const gallery = document.querySelector('[code-path="src/pages/ProductPage.tsx:58:9"]');
  const thumbnails = [...(gallery?.querySelectorAll('[code-path="src/pages/ProductPage.tsx:67:17"]') || [])];
  if (!thumbnails.length) return;

  const [from, to] = range;
  thumbnails.forEach((thumbnail, index) => {
    thumbnail.style.display = index >= from && index < to ? "" : "none";
  });
  thumbnails[from]?.click();
}

function syncColorGallery() {
  const gallery = document.querySelector('[code-path="src/pages/ProductPage.tsx:58:9"]');
  if (!gallery) return;
  const slug = coutureSlug();
  const ranges = colorPhotoRanges[slug];
  if (!ranges) {
    if (gallery.dataset.colorGallery) {
      delete gallery.dataset.colorGallery;
      gallery.querySelectorAll('button').forEach((button) => { button.style.display = ''; });
    }
    return;
  }
  const colors = [...document.querySelectorAll('[code-path="src/pages/ProductPage.tsx:132:19"]')];
  const selected = colors.find((button) => button.classList.contains('bg-black'));
  const color = (selected || colors[0])?.textContent.trim();
  if (!ranges[color]) return;
  const key = `${slug}:${color}`;
  if (gallery.dataset.colorGallery === key) return;
  gallery.dataset.colorGallery = key;
  showColorPhotos(ranges[color]);
}

